#!/usr/bin/env python3
import datetime, hashlib, json, os, sys, time, uuid
from pathlib import Path
sys.path.insert(0, str(Path.cwd() / 'scripts/aws'))
from aws_cli import observe

ACCOUNT = '000000000000'
REGION = 'us-east-1'
PREFIX = 'stackd-sns-esrc-' + uuid.uuid4().hex[:12]
OUT = Path('testdata/aws/sns/encryption_service_sources.json')
ENV = dict(os.environ, AWS_DEFAULT_REGION=REGION, AWS_REGION=REGION, AWS_MAX_ATTEMPTS='2', AWS_PAGER='')
START = time.time()
CAP = {'source': 'Native EventBridge to encrypted SNS to raw SQS, source-condition boundary', 'account': ACCOUNT, 'region': REGION, 'prefix': PREFIX, 'started_ms': int(START*1000), 'source_references': ['https://docs.aws.amazon.com/sns/latest/dg/sns-key-management.html', 'https://docs.aws.amazon.com/eventbridge/latest/userguide/eb-rule-dlq.html', 'https://docs.aws.amazon.com/eventbridge/latest/APIReference/API_RetryPolicy.html'], 'source_revisions': {'stackd': '3607cc0ab878a09119cdf25412a4c8b28d21ece0'}, 'observations': [], 'receipts': [], 'windows': [], 'cloudtrail': {'events': [], 'lookups': []}, 'cleanup': [], 'owned_resources': {'rules': {}, 'topics': {}, 'subscriptions': {}, 'queues': {}}, 'limitations': ['Existing encryption.json and eventbridge.json were read for request/receipt patterns; neither contains an embedded probe source in the current revision.', 'No inference of a cold KMS request is made from elapsed time. Fresh unique topic contexts isolate grants; captured KMS management events establish observed KMS calls.', 'Queue absence is bounded and never classified as denial without an actual correlated target DLQ outcome.', 'Only same-account custom-bus EventBridge service-principal publication is measured. No execution role, caller STS credential, or IAM/Organizations policy is created or changed.']}
R = CAP['owned_resources']

def ms(): return int(time.time()*1000)
def save(): OUT.write_text(json.dumps(CAP, indent=2) + '\n')
def call(label, service, operation, args=None, strict=True, cleanup=False):
    item={'label':label,'service':service,'operation':operation,'input':args or {},'request_started_ms':ms()}
    result=observe(service, operation, args, ENV)
    item.update(result=result,response_observed_ms=ms())
    CAP['cleanup' if cleanup else 'observations'].append(item)
    save()
    if strict and result['code']!='Success': raise RuntimeError(label+': '+json.dumps(result))
    return result.get('output',{}) if strict else result

def policy(statements): return json.dumps({'Version':'2012-10-17','Statement':statements})
def queue_policy(kind, principal, sources):
    q=R['queues'][kind]
    call('queue-policy-'+kind,'sqs','set-queue-attributes',{'QueueUrl':q['url'],'Attributes':{'Policy':policy([{'Effect':'Allow','Principal':{'Service':principal},'Action':'sqs:SendMessage','Resource':q['arn'],'Condition':{'ArnEquals':{'aws:SourceArn':sources},'StringEquals':{'aws:SourceAccount':ACCOUNT}}}])}})

def receive(round_name, cases, seconds=100):
    started=ms(); deadline=time.monotonic()+seconds; pending=set(cases)
    while pending and time.monotonic()<deadline:
        for kind,q in R['queues'].items():
            out=call('receive-'+round_name+'-'+kind,'sqs','receive-message',{'QueueUrl':q['url'],'WaitTimeSeconds':2,'MaxNumberOfMessages':10,'MessageAttributeNames':['All'],'MessageSystemAttributeNames':['All']})
            for m in out.get('Messages',[]):
                event=json.loads(m['Body']); attrs={k:v.get('StringValue') for k,v in m.get('MessageAttributes',{}).items()}
                c=event.get('detail',{}).get('case'); expected=CAP['events'].get(round_name,{}).get(c)
                correlated=bool(expected and event.get('id')==expected['event_id'] and event.get('detail',{}).get('probe')==PREFIX and (kind=='collector' or attrs.get('TARGET_ARN')==R['topics'].get(c)))
                CAP['receipts'].append({'round':round_name,'case':c,'queue':kind,'observed_ms':ms(),'message':m,'decoded_event':event,'decoded_message_attributes':attrs,'correlated':correlated})
                call('delete-receipt-'+kind,'sqs','delete-message',{'QueueUrl':q['url'],'ReceiptHandle':m['ReceiptHandle']})
                if correlated: pending.discard(c)
    CAP['windows'].append({'round':round_name,'started_ms':started,'ended_ms':ms(),'maximum_seconds':seconds,'pending_cases':sorted(pending)})
    save()
    return pending

key=None; bus=False
try:
    identity=call('identity-before-mutation','sts','get-caller-identity')
    CAP['identity']=identity
    if identity['Account']!=ACCOUNT: raise RuntimeError('Unexpected account; no mutations permitted')
    org=call('organization-read-only','organizations','describe-organization',strict=False)
    orgid=org.get('output',{}).get('Organization',{}).get('Id')
    CAP['organization_id']=orgid
    names=['unconditional','source-rule','source-topic','source-account','null-arn','null-account','null-org']
    if orgid: names.append('source-org')
    call('create-bus','events','create-event-bus',{'Name':PREFIX}); bus=True; R['bus']=PREFIX
    for c in names:
        name=PREFIX+'-'+c
        arn=call('rule-'+c,'events','put-rule',{'Name':name,'EventBusName':PREFIX,'EventPattern':json.dumps({'source':[PREFIX],'detail':{'case':[c]}})})['RuleArn']
        R['rules'][c]={'name':name,'arn':arn}
        R['topics'][c]='arn:aws:sns:'+REGION+':'+ACCOUNT+':'+name
    cond={'unconditional':{},'source-rule':{'ArnEquals':{'aws:SourceArn':R['rules']['source-rule']['arn']}},'source-topic':{'ArnEquals':{'aws:SourceArn':R['topics']['source-topic']}},'source-account':{'StringEquals':{'aws:SourceAccount':ACCOUNT}},'null-arn':{'Null':{'aws:SourceArn':'true'}},'null-account':{'Null':{'aws:SourceAccount':'true'}},'null-org':{'Null':{'aws:SourceOrgID':'true'}}}
    if orgid: cond['source-org']={'StringEquals':{'aws:SourceOrgID':orgid}}
    statements=[{'Sid':'OwnerAdministration','Effect':'Allow','Principal':{'AWS':'arn:aws:iam::'+ACCOUNT+':root'},'Action':'kms:*','Resource':'*'}]
    for c in names:
        condition=json.loads(json.dumps(cond[c])); condition.setdefault('StringEquals',{})['kms:EncryptionContext:aws:sns:topicArn']=R['topics'][c]
        statements.append({'Sid':c.replace('-',''),'Effect':'Allow','Principal':{'Service':'events.amazonaws.com'},'Action':['kms:GenerateDataKey*','kms:Decrypt'],'Resource':'*','Condition':condition})
    CAP['case_conditions']=cond
    key=call('create-key','kms','create-key',{'Description':PREFIX,'Policy':policy(statements),'Tags':[{'TagKey':'stackd-probe','TagValue':PREFIX}]})['KeyMetadata']
    R['key']=key
    call('read-key-policy','kms','get-key-policy',{'KeyId':key['KeyId'],'PolicyName':'default'})
    for kind in ['collector','dlq']:
        url=call('queue-'+kind,'sqs','create-queue',{'QueueName':PREFIX+'-'+kind,'Attributes':{'SqsManagedSseEnabled':'false'}})['QueueUrl']
        R['queues'][kind]={'url':url}
        attrs=call('queue-attributes-'+kind,'sqs','get-queue-attributes',{'QueueUrl':url,'AttributeNames':['QueueArn','SqsManagedSseEnabled']})['Attributes']; R['queues'][kind]['arn']=attrs['QueueArn']
    queue_policy('collector','sns.amazonaws.com',list(R['topics'].values()))
    queue_policy('dlq','events.amazonaws.com',[r['arn'] for r in R['rules'].values()])
    for c in names:
        topic=call('topic-'+c,'sns','create-topic',{'Name':PREFIX+'-'+c,'Attributes':{'KmsMasterKeyId':key['Arn']}})['TopicArn']
        assert topic==R['topics'][c]
        call('topic-policy-'+c,'sns','set-topic-attributes',{'TopicArn':topic,'AttributeName':'Policy','AttributeValue':policy([{'Effect':'Allow','Principal':{'Service':'events.amazonaws.com'},'Action':'sns:Publish','Resource':topic,'Condition':{'ArnEquals':{'aws:SourceArn':R['rules'][c]['arn']},'StringEquals':{'aws:SourceAccount':ACCOUNT}}}])})
        sub=call('subscribe-'+c,'sns','subscribe',{'TopicArn':topic,'Protocol':'sqs','Endpoint':R['queues']['collector']['arn'],'Attributes':{'RawMessageDelivery':'true'},'ReturnSubscriptionArn':True})['SubscriptionArn']; R['subscriptions'][c]=sub
        result=call('target-'+c,'events','put-targets',{'Rule':R['rules'][c]['name'],'EventBusName':PREFIX,'Targets':[{'Id':'sns','Arn':topic,'RetryPolicy':{'MaximumRetryAttempts':0,'MaximumEventAgeInSeconds':60},'DeadLetterConfig':{'Arn':R['queues']['dlq']['arn']}}]})
        if result['FailedEntryCount']: raise RuntimeError('Failed target setup '+c)
    CAP['events']={}
    for round_name in ['initial']:
        CAP['events'][round_name]={}
        for c in names:
            detail={'probe':PREFIX,'case':c,'round':round_name,'nonce':uuid.uuid4().hex}
            args={'Entries':[{'EventBusName':PREFIX,'Source':PREFIX,'DetailType':'encrypted SNS KMS source condition','Detail':json.dumps(detail)}]}
            result=call('publish-'+round_name+'-'+c,'events','put-events',args)
            if result['FailedEntryCount']: raise RuntimeError('PutEvents failed '+c)
            CAP['events'][round_name][c]={'event_id':result['Entries'][0]['EventId'],'detail':detail,'put_events_observation_label':'publish-'+round_name+'-'+c}
        receive(round_name,names)
    CAP['delivery_finished_ms']=ms(); save()
except Exception as e:
    CAP['failure']=str(e); save()
finally:
    for c,r in R['rules'].items():
        call('remove-target-'+c,'events','remove-targets',{'Rule':r['name'],'EventBusName':PREFIX,'Ids':['sns'],'Force':True},strict=False,cleanup=True)
        call('delete-rule-'+c,'events','delete-rule',{'Name':r['name'],'EventBusName':PREFIX,'Force':True},strict=False,cleanup=True)
        call('verify-rule-'+c,'events','describe-rule',{'Name':r['name'],'EventBusName':PREFIX},strict=False,cleanup=True)
    if bus:
        call('delete-bus','events','delete-event-bus',{'Name':PREFIX},strict=False,cleanup=True)
        call('verify-bus','events','describe-event-bus',{'Name':PREFIX},strict=False,cleanup=True)
    for c,sub in R['subscriptions'].items():
        call('delete-subscription-'+c,'sns','unsubscribe',{'SubscriptionArn':sub},strict=False,cleanup=True)
        call('verify-subscription-'+c,'sns','get-subscription-attributes',{'SubscriptionArn':sub},strict=False,cleanup=True)
    for c,topic in R['topics'].items():
        call('delete-topic-'+c,'sns','delete-topic',{'TopicArn':topic},strict=False,cleanup=True)
        call('verify-topic-'+c,'sns','get-topic-attributes',{'TopicArn':topic},strict=False,cleanup=True)
    for kind,q in R['queues'].items():
        call('delete-queue-'+kind,'sqs','delete-queue',{'QueueUrl':q['url']},strict=False,cleanup=True)
        call('verify-queue-'+kind,'sqs','get-queue-attributes',{'QueueUrl':q['url'],'AttributeNames':['QueueArn']},strict=False,cleanup=True)
    if key:
        call('schedule-key-deletion','kms','schedule-key-deletion',{'KeyId':key['KeyId'],'PendingWindowInDays':7},strict=False,cleanup=True)
        call('verify-key-pending-deletion','kms','describe-key',{'KeyId':key['KeyId']},strict=False,cleanup=True)
    CAP['cleanup_finished_ms']=ms(); save()

# The management-history scan deliberately searches errorMessage as well as requestParameters/resources.
# KMS denied events can omit request parameters and resource lists.
if key:
    end=CAP.get('delivery_finished_ms',CAP['cleanup_finished_ms'])/1000
    args={'LookupAttributes':[{'AttributeKey':'EventSource','AttributeValue':'kms.amazonaws.com'}],'StartTime':datetime.datetime.fromtimestamp(START-5,datetime.timezone.utc).isoformat(),'EndTime':datetime.datetime.fromtimestamp(end+5,datetime.timezone.utc).isoformat(),'MaxResults':50}
    deadline=time.monotonic()+660; seen=set()
    CAP['cloudtrail']['window']={'start':args['StartTime'],'end':args['EndTime'],'maximum_poll_seconds':660}
    while True:
        page_args=dict(args); pages=0; matched=0
        while True:
            started=ms(); res=observe('cloudtrail','lookup-events',page_args,ENV); ended=ms(); pages+=1
            lookup={'input':page_args,'request_started_ms':started,'response_observed_ms':ended,'result_code':res['code']}
            if res['code']!='Success': lookup['error']=res; CAP['cloudtrail']['lookups'].append(lookup); break
            out=res['output']; lookup['returned_event_count']=len(out.get('Events',[])); lookup['next_token']=out.get('NextToken')
            for item in out.get('Events',[]):
                event=json.loads(item['CloudTrailEvent'])
                if key['KeyId'] not in json.dumps(event): continue
                matched+=1
                if event['eventID'] in seen: continue
                seen.add(event['eventID'])
                # Stable aliases redact AWS-internal credentials without misidentifying them as caller-issued STS keys.
                ident=event.get('userIdentity',{})
                if ident.get('accessKeyId'):
                    category='AWS_INTERNAL_FAS' if ident.get('invokedBy') in ['sns.amazonaws.com','events.amazonaws.com'] or ident.get('type')=='AWSService' else 'CALLER'
                    ident['accessKeyId']='REDACTED_'+category+'_ACCESS_KEY_SHA256_'+hashlib.sha256(ident['accessKeyId'].encode()).hexdigest()[:16]
                CAP['cloudtrail']['events'].append({'first_observed_ms':ended,'lookup_event_id':item.get('EventId'),'event':event})
            CAP['cloudtrail']['lookups'].append(lookup); save()
            token=out.get('NextToken')
            if not token: break
            page_args=dict(args,NextToken=token); time.sleep(0.6)
        successes={x['event'].get('requestParameters',{}).get('encryptionContext',{}).get('aws:sns:topicArn') for x in CAP['cloudtrail']['events'] if x['event']['eventName']=='GenerateDataKey' and not x['event'].get('errorCode') and x['event'].get('requestParameters')}
        denied=[x for x in CAP['cloudtrail']['events'] if x['event'].get('errorCode') and x['event']['eventName'] in ['GenerateDataKey','Decrypt']]
        print(json.dumps({'cloudtrail_owned_events':len(seen),'successful_generate_contexts':len(successes),'denied_kms_calls':len(denied),'pages':pages}),flush=True)
        if (len(successes)>=4 and len(denied)>=len(R['topics'])-4) or time.monotonic()>=deadline: break
        time.sleep(30)
    CAP['cloudtrail']['poll_finished_ms']=ms()
CAP['probe_source']={'filename':'sns_event_source_conditions_probe.py','sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'content':Path(__file__).read_text(),'aws_cli_helper_sha256':hashlib.sha256(Path('scripts/aws/aws_cli.py').read_bytes()).hexdigest()}
CAP['finished_ms']=ms(); save()
print(json.dumps({'fixture':str(OUT),'failure':CAP.get('failure'),'receipts':[(r['case'],r['queue']) for r in CAP['receipts']],'key_id':key['KeyId'] if key else None}),flush=True)
